-- AUREKA quality backend enablement + full 2026 indicator master
-- Adds Data API schema usage and inserts missing 2026 indicator profiles from the AUREKA source master.
GRANT USAGE ON SCHEMA aureka_quality TO authenticated;
GRANT SELECT, INSERT, UPDATE ON aureka_quality.indicator_profiles TO authenticated;
GRANT SELECT, INSERT, UPDATE ON aureka_quality.quality_records TO authenticated;
GRANT SELECT, INSERT, UPDATE ON aureka_quality.quality_record_responses TO authenticated;
GRANT SELECT ON aureka_quality.audit_log TO authenticated;

