INSERT INTO aureka_quality.indicator_profiles (
  profile_year, code, room_id, unit_name, title, indicator_type, category,
  unit_of_measure, target_text, target_operator, target_value,
  numerator_definition, denominator_definition, measurement_grain,
  schema_json, options_json, version, status, is_active
)
SELECT
  2026, src.code, r.id, r.name, src.title, src.type, NULL, NULL,
  NULLIF(src.target,''),
  CASE
    WHEN src.target LIKE '≥%' THEN '>='
    WHEN src.target LIKE '≤%' THEN '<='
    WHEN src.target LIKE '=%' THEN '='
    ELSE '='
  END,
  NULL,
  NULLIF(src.numerator,''), NULLIF(src.denominator,''), src.model,
  jsonb_build_object('source','AUREKA_Universal_Quality_Logbook_Engine_v2','collection_mode',src.model),
  '[]'::jsonb, 1, 'published', COALESCE(src.active,true)
FROM src
JOIN public.master_rooms r ON r.name=src.unit
ON CONFLICT (profile_year,code,version) DO NOTHING;
